def fig(f, cap, w=560):
    return f'<figure class="lab-fig" style="--fw:{w}px"><img src="img/lab/{f}" alt="{cap}" loading="lazy"><figcaption>{cap}</figcaption></figure>'


def figs(*items):
    return '<div class="lab-figs">' + "".join(fig(*i) for i in items) + "</div>"


