  ("Lens qoidasi nimani ifodalaydi?", ["Induksion tok o‘zini hosil qilgan oqim o‘zgarishiga qarshilik qiladi", "Induksion tok doim soat strelkasi bo‘yicha", "EYuK qarshilikka proporsional", "Tok oqimni kuchaytiradi"], 0, "Bu energiyaning saqlanish qonunining natijasi."),
  (r"O‘zinduksiya EYuK:", [r"\(-L\,dI/dt\)", r"\(-L\,I\)", r"\(L/I\)", r"\(-dL/dI\)"], 0, r"\(\Phi=LI\) bo‘lgani uchun."),
