  (r"G‘altakda \(R_L=6\) Om, 50 Gs da \(Z=10\) Om. Induktiv qarshilik:", ["8 Om", "4 Om", "16 Om", "10 Om"], 0, r"\(X_L=\sqrt{Z^2-R^2}\)."),
  (r"\(X_L=31{,}4\) Om, \(f=50\) Gs. Induktivlik:", ["0,1 Gn", "1 Gn", "0,01 Gn", "31,4 Gn"], 0, r"\(L=X_L/(2\pi f)\)."),
