  (r"Uchburchak ulashda tekis yuklamada liniya toki:", [r"\(\sqrt3\) marta faza tokidan katta", "faza tokiga teng", "3 marta katta", "nolga teng"], 0, "Liniya toki ikki faza tokining vektor ayirmasi."),
  ("Yulduz ulashda tekis yuklamada neytral simdagi tok:", ["nolga teng", "faza tokiga teng", r"\(\sqrt3\) marta katta", "3 marta katta"], 0, "120° siljigan uch teng vektor yig‘indisi nol."),
  ("Notekis yuklamada neytral sim uzilsa nima bo‘ladi?", ["Faza kuchlanishlari tenglashmay qoladi", "Barcha lampalar o‘chadi", "Faza kuchlanishlari o‘zgarmaydi", "Liniya kuchlanishi nolga tushadi"], 0, "Yuklamasi katta fazada kuchlanish kamayadi, boshqalarida ortadi."),
